foreach ($uuid in $data.Keys) {
    $outPath = "$baseDir\completed_synthesis\$uuid.json"
    $inPath = "$baseDir\pending_synthesis\$uuid.json"
    $data[$uuid] | Out-File -FilePath $outPath -Encoding UTF8
    Remove-Item -Path $inPath -Force -ErrorAction SilentlyContinue
}
